def _build_group_svg(curves: List[Dict[str, object]], group_prefix: str) -> str:
    """Group path elements cleanly by animation group to minimize DOM overhead."""
    grouped: Dict[str, List[str]] = {}
    for idx, curve in enumerate(curves):
        grp = str(curve["group"])
        dash = str(curve["dash"])
        flow_cls = str(curve["cls"])
        dash_attr = f' stroke-dasharray="{dash}"' if dash else ""
        cls_attr = f' class="ns-flux-path {flow_cls}"' if flow_cls else ' class="ns-flux-path"'
        path_el = (
            f'<path{cls_attr} d="{curve["d"]}" fill="none" '
            f'stroke="{curve["stroke"]}" stroke-width="{curve["width"]}" '
            f'stroke-opacity="{curve["opacity"]}" stroke-linecap="round"{dash_attr}/>'
        )
        grouped.setdefault(grp, []).append(path_el)

        # Pair continuous field lines with a gentle travelling pulse along the spline
        if not dash:
            pulse_cls = "ns-flux-pulse" if idx % 2 == 0 else "ns-flux-pulse-rev"
            pulse_opacity = round(min(0.36, float(curve["opacity"]) + 0.12), 2)
            pulse_width = round(float(curve["width"]) + 0.25, 2)
            pulse_el = (
                f'<path class="ns-flux-path {pulse_cls}" d="{curve["d"]}" fill="none" '
                f'stroke="{curve["stroke"]}" stroke-width="{pulse_width}" '
                f'stroke-opacity="{pulse_opacity}" stroke-linecap="round" '
                f'stroke-dasharray="56 144"/>'
            )
            grouped[grp].append(pulse_el)

    parts: List[str] = []
    for grp, paths in grouped.items():
        parts.append(f'<g class="ns-flux-group ns-{group_prefix}-{grp}">' + "".join(paths) + "</g>")
    return "".join(parts)


def render_flux_background() -> None:
    """Render subtle animated magnetic flux lines across the canvas and hero brain zone."""
    stream_svg_body = _build_group_svg(_STREAM_CURVES, "stream")
    dipole_svg_body = _build_group_svg(_DIPOLE_CURVES, "dipole")

    render_html(
        f"""
        <div class="ns-flux-bg" aria-hidden="true">
            <svg class="ns-flux-svg ns-flux-global" viewBox="0 0 1600 1000" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg">
                {stream_svg_body}
            </svg>
        </div>
        <div class="ns-flux-hero-bg" aria-hidden="true">
            <svg class="ns-flux-svg ns-flux-hero" viewBox="0 0 1600 1000" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg">
                {dipole_svg_body}
            </svg>
        </div>
        """
    )
